from decimal import Decimal, InvalidOperation
from fractions import Fraction


def allocate_by_ratios(total, ratios):
    if not isinstance(total, str):
        raise ValueError('total must be a string')
    try:
        total_value = Decimal(total)
    except (InvalidOperation, ValueError, TypeError):
        raise ValueError('invalid total') from None
    if not total_value.is_finite():
        raise ValueError('total must be finite')
    total_cents_fraction = Fraction(total_value) * 100
    if total_cents_fraction.denominator != 1:
        raise ValueError('total must have at most 2 decimal places')
    if not isinstance(ratios, list) or len(ratios) == 0:
        raise ValueError('ratios must be a non-empty list')
    weights = []
    for entry in ratios:
        if isinstance(entry, bool):
            raise ValueError('invalid ratio')
        elif isinstance(entry, int):
            weight = Fraction(entry)
        elif isinstance(entry, Decimal):
            if not entry.is_finite():
                raise ValueError('ratio must be finite')
            weight = Fraction(entry)
        elif isinstance(entry, str):
            try:
                parsed = Decimal(entry)
            except (InvalidOperation, ValueError, TypeError):
                raise ValueError('invalid ratio') from None
            if not parsed.is_finite():
                raise ValueError('ratio must be finite')
            weight = Fraction(parsed)
        else:
            raise ValueError('invalid ratio')
        if weight < 0:
            raise ValueError('ratio must be non-negative')
        weights.append(weight)
    if not any(weight > 0 for weight in weights):
        raise ValueError('at least one ratio must be positive')
    is_negative = total_value < 0
    total_cents = int(abs(total_cents_fraction))
    total_weight = sum(weights, Fraction(0))
    cents = []
    remainders = []
    for weight in weights:
        if weight == 0:
            cents.append(0)
            remainders.append(Fraction(0))
        else:
            exact = Fraction(total_cents) * weight / total_weight
            floor_cents = exact.numerator // exact.denominator
            cents.append(floor_cents)
            remainders.append(exact - floor_cents)
    remaining = total_cents - sum(cents)
    order = sorted((i for i, weight in enumerate(weights) if weight > 0), key=lambda i: (-remainders[i], -weights[i], i))
    for index in order[:remaining]:
        cents[index] += 1
    result = []
    for amount_cents in cents:
        if amount_cents == 0:
            result.append(Decimal('0.00'))
        else:
            text = f'{amount_cents // 100}.{amount_cents % 100:02d}'
            if is_negative:
                text = '-' + text
            result.append(Decimal(text))
    return result

