from decimal import Decimal, InvalidOperation, ROUND_HALF_UP, localcontext

_FREQUENCIES = {
    'annually': 1,
    'semiannually': 2,
    'quarterly': 4,
    'monthly': 12,
    'weekly': 52,
    'daily': 365,
    'continuous': None,
}
_QUANTUM = Decimal('0.000001')


def _parse_percent(value):
    if not isinstance(value, str):
        raise ValueError('percent must be a string')
    try:
        parsed = Decimal(value)
    except (InvalidOperation, ValueError, TypeError):
        raise ValueError('invalid percent') from None
    if not parsed.is_finite():
        raise ValueError('percent must be finite')
    if parsed <= Decimal('-100'):
        raise ValueError('percent must be greater than -100')
    return parsed


def _parse_frequency(value):
    if not isinstance(value, str):
        raise ValueError('frequency must be a string')
    key = value.strip().lower()
    if key not in _FREQUENCIES:
        raise ValueError('invalid frequency')
    return _FREQUENCIES[key]


def _quantize(value):
    with localcontext() as ctx:
        if value.is_zero():
            ctx.prec = 50
        else:
            ctx.prec = max(50, value.adjusted() + 10)
        return value.quantize(_QUANTUM, rounding=ROUND_HALF_UP)


def apr_to_apy(apr_percent, frequency):
    percent = _parse_percent(apr_percent)
    periods = _parse_frequency(frequency)
    with localcontext() as ctx:
        ctx.prec = 50
        rate = percent / Decimal(100)
        if periods is None:
            result = (rate.exp() - Decimal(1)) * Decimal(100)
        else:
            result = ((Decimal(1) + rate / Decimal(periods)) ** periods - Decimal(1)) * Decimal(100)
    return _quantize(result)


def apy_to_apr(apy_percent, frequency):
    percent = _parse_percent(apy_percent)
    periods = _parse_frequency(frequency)
    with localcontext() as ctx:
        ctx.prec = 50
        yield_rate = percent / Decimal(100)
        if periods is None:
            result = (Decimal(1) + yield_rate).ln() * Decimal(100)
        else:
            result = Decimal(periods) * ((Decimal(1) + yield_rate) ** (Decimal(1) / Decimal(periods)) - Decimal(1)) * Decimal(100)
    return _quantize(result)

