import itertools
import re
from datetime import date
from decimal import Decimal, InvalidOperation
from fractions import Fraction

_DATE_RE = re.compile(r'\d{4}-\d{2}-\d{2}')


def _parse_entries(entries):
    if not isinstance(entries, list):
        raise ValueError('entries must be a list')
    parsed = []
    seen_ids = set()
    for entry in entries:
        if not isinstance(entry, dict):
            raise ValueError('entry must be a dict')
        if 'id' not in entry or 'date' not in entry or 'amount' not in entry:
            raise ValueError('entry is missing a required key')
        entry_id = entry['id']
        if not isinstance(entry_id, str) or len(entry_id) == 0:
            raise ValueError('id must be a non-empty string')
        if entry_id in seen_ids:
            raise ValueError('duplicate id')
        seen_ids.add(entry_id)
        date_value = entry['date']
        if not isinstance(date_value, str) or _DATE_RE.fullmatch(date_value) is None:
            raise ValueError('date must be in YYYY-MM-DD form')
        try:
            parsed_date = date(int(date_value[0:4]), int(date_value[5:7]), int(date_value[8:10]))
        except ValueError:
            raise ValueError('date must be a real calendar date') from None
        amount_value = entry['amount']
        if not isinstance(amount_value, str):
            raise ValueError('amount must be a string')
        try:
            amount = Decimal(amount_value)
        except (InvalidOperation, ValueError, TypeError):
            raise ValueError('invalid amount') from None
        if not amount.is_finite():
            raise ValueError('amount must be finite')
        if (Fraction(amount) * 100).denominator != 1:
            raise ValueError('amount must have at most 2 decimal places')
        parsed.append({'id': entry_id, 'date': parsed_date, 'amount': amount})
    return parsed


def reconcile(book, bank, tolerance_days=3):
    if isinstance(tolerance_days, bool) or not isinstance(tolerance_days, int):
        raise ValueError('tolerance_days must be an int')
    if tolerance_days < 0 or tolerance_days > 31:
        raise ValueError('tolerance_days must be between 0 and 31')
    book_entries = _parse_entries(book)
    bank_entries = _parse_entries(bank)
    used_book = set()
    used_bank = set()
    internal_matches = []
    candidates = []
    for bank_index, bank_entry in enumerate(bank_entries):
        for book_index, book_entry in enumerate(book_entries):
            if bank_entry['amount'] != book_entry['amount']:
                continue
            difference = abs((bank_entry['date'] - book_entry['date']).days)
            if difference <= tolerance_days:
                candidates.append((difference, bank_entry['date'], bank_entry['id'], book_entry['id'], bank_index, book_index))
    candidates.sort(key=lambda item: (item[0], item[1], item[2], item[3]))
    for _difference, _bank_date, _bank_id, _book_id, bank_index, book_index in candidates:
        if bank_index in used_bank or book_index in used_book:
            continue
        used_bank.add(bank_index)
        used_book.add(book_index)
        bank_entry = bank_entries[bank_index]
        internal_matches.append((bank_entry['date'], bank_entry['id'], {'bank_id': bank_entry['id'], 'book_ids': [book_entries[book_index]['id']]}))
    remaining_bank_order = sorted((i for i in range(len(bank_entries)) if i not in used_bank), key=lambda i: (bank_entries[i]['date'], bank_entries[i]['id']))
    for bank_index in remaining_bank_order:
        bank_entry = bank_entries[bank_index]
        eligible = []
        for book_index, book_entry in enumerate(book_entries):
            if book_index in used_book:
                continue
            if abs((bank_entry['date'] - book_entry['date']).days) <= tolerance_days:
                eligible.append(book_index)
        chosen = None
        for size in (2, 3):
            best = None
            best_key = None
            for combo in itertools.combinations(eligible, size):
                total = sum((book_entries[i]['amount'] for i in combo), Decimal('0'))
                if total != bank_entry['amount']:
                    continue
                max_difference = max(abs((bank_entry['date'] - book_entries[i]['date']).days) for i in combo)
                sorted_ids = tuple(sorted(book_entries[i]['id'] for i in combo))
                key = (max_difference, sorted_ids)
                if best_key is None or key < best_key:
                    best_key = key
                    best = combo
            if best is not None:
                chosen = best
                break
        if chosen is not None:
            for book_index in chosen:
                used_book.add(book_index)
            used_bank.add(bank_index)
            sorted_ids = sorted(book_entries[i]['id'] for i in chosen)
            internal_matches.append((bank_entry['date'], bank_entry['id'], {'bank_id': bank_entry['id'], 'book_ids': sorted_ids}))
    internal_matches.sort(key=lambda item: (item[0], item[1]))
    matches = [item[2] for item in internal_matches]
    unmatched_book = [entry['id'] for index, entry in sorted(enumerate(book_entries), key=lambda pair: (pair[1]['date'], pair[1]['id'])) if index not in used_book]
    unmatched_bank = [entry['id'] for index, entry in sorted(enumerate(bank_entries), key=lambda pair: (pair[1]['date'], pair[1]['id'])) if index not in used_bank]
    return {'matches': matches, 'unmatched_book': unmatched_book, 'unmatched_bank': unmatched_bank}
